# still keeps lease_expires_at ahead of different-identity expiry claims.
DEFAULT_PRISM_LEDGER_LEASE_HEARTBEAT_SECONDS = (
    DEFAULT_WRITER_LEASE_ADOPTION_SILENCE_SECONDS / 4
)
